"""Lock-parity check run at image build time: it must pass on parity and fail loudly otherwise."""

import subprocess
import sys
from pathlib import Path

import check_lock_parity
import pytest

SCRIPT = Path(check_lock_parity.__file__)

EXPORT = """\
# This file was autogenerated by uv via the following command:
#    uv export --locked --no-dev --no-emit-project
grpcio==1.85.1 \\
    --hash=sha256:aaaa
    # via crosscodex-ingestion
Some_Pkg==2.0 \\
    --hash=sha256:bbbb
torch==2.15.0+cpu \\
    --hash=sha256:cccc
colorama==0.4.6 ; sys_platform == 'nonexistent-os' \\
    --hash=sha256:dddd
"""

FREEZE_OK = "grpcio==1.85.1\nsome-pkg==2.0\ntorch==2.15.0+cpu\n"


def _run(tmp_path: Path, export: str, freeze: str) -> subprocess.CompletedProcess[str]:
    (tmp_path / "requirements.txt").write_text(export)
    (tmp_path / "freeze.txt").write_text(freeze)
    return subprocess.run(
        [sys.executable, str(SCRIPT), str(tmp_path / "requirements.txt"), str(tmp_path / "freeze.txt")],
        capture_output=True,
        text=True,
        check=False,
    )


def test_parity_passes_with_normalized_names_and_skipped_markers(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, FREEZE_OK)
    assert result.returncode == 0, result.stderr


def test_version_mismatch_fails_with_diff(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, FREEZE_OK.replace("1.85.1", "1.85.3"))
    assert result.returncode == 1
    assert "~ grpcio: lock 1.85.1, installed 1.85.3" in result.stderr


def test_local_version_suffix_must_match(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, FREEZE_OK.replace("2.15.0+cpu", "2.15.0"))
    assert result.returncode == 1
    assert "~ torch: lock 2.15.0+cpu, installed 2.15.0" in result.stderr


def test_extra_installed_package_fails(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, FREEZE_OK + "grpcio-tools==1.85.3\n")
    assert result.returncode == 1
    assert "+ grpcio-tools==1.85.3  installed but not in the lock" in result.stderr


def test_missing_package_fails(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, "grpcio==1.85.1\ntorch==2.15.0+cpu\n")
    assert result.returncode == 1
    assert "- some-pkg==2.0  in the lock but not installed" in result.stderr


def test_unpinned_input_is_rejected(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, "grpcio>=1.0\n")
    assert result.returncode == 2
    assert "not an exact" in result.stderr


def test_unparseable_input_is_rejected(tmp_path: Path) -> None:
    result = _run(tmp_path, EXPORT, "this is not a requirement\n")
    assert result.returncode == 2


def test_wrong_argument_count_prints_usage() -> None:
    result = subprocess.run([sys.executable, str(SCRIPT)], capture_output=True, text=True, check=False)
    assert result.returncode == 2
    assert "Usage" in result.stderr


@pytest.mark.parametrize("missing", ["requirements.txt", "freeze.txt"])
def test_missing_file_is_rejected(tmp_path: Path, missing: str) -> None:
    (tmp_path / "requirements.txt").write_text(EXPORT)
    (tmp_path / "freeze.txt").write_text(FREEZE_OK)
    (tmp_path / missing).unlink()
    result = subprocess.run(
        [sys.executable, str(SCRIPT), str(tmp_path / "requirements.txt"), str(tmp_path / "freeze.txt")],
        capture_output=True,
        text=True,
        check=False,
    )
    assert result.returncode == 2
